    @Test
    void matchesEachResultToItsStudentByUsernameWhateverTheOrder() {
        // bob is ready but has no result yet, as after his identity is confirmed and before he is regraded.
        List<SubmissionValidationResult> submissions = List.of(submission("alice"), submission("bob"),
                submission("carol"));
        List<StudentGradingResult> results = List.of(result("carol", 2), result("alice", 3));
        GradingSettings settings = GradingSettings.current();

        GradingAttempt attempt = GradingAttempt.assemble(LocalDateTime.now(), temporary, temporary, settings,
                submissions, results, submission -> null, StyleRules.load(settings.style().rules()));

        Map<String, StudentOutcome> byName = attempt.students().stream()
                .collect(Collectors.toMap(StudentOutcome::username, outcome -> outcome));
        assertEquals(3.0, byName.get("alice").grading().totalScore());
        assertNull(byName.get("bob").grading());
        assertEquals(2.0, byName.get("carol").grading().totalScore());
    }

    private SubmissionValidationResult submission(String username) {
        return new SubmissionValidationResult(temporary.resolve(username), username, null, Map.of(), List.of());
    }

    private static StudentGradingResult result(String username, double score) {
        return new StudentGradingResult(username, List.of(new QuestionGradingResult("Q1a",
                QuestionGradingResult.Status.GRADED, score, (int) score, 0, null, null, "")));
    }
